    ["Follow path"] = "Segui il percorso",
    ["Follow the foundry floor to ^Prototype Pantheon^."] = "Segui il pavimento della fonderia fino a ^Prototype Pantheon^.",
    ["Follow the map from the entrance to ^The Tarragrue^."] = "Segui la mappa dall'ingresso fino a ^The Tarragrue^.",
    ["Follow the mineshaft into the next room. After a lengthy dialog, speak to ^Norushen^ to start the encounter."] = "Segui il pozzo minerario nella stanza successiva. Dopo un lungo dialogo, parla con ^Norushen^ per iniziare lo scontro.",
    ["Follow the path all the way back to find ^Il'gynoth, Corruption Reborn^."] = "Segui tutto il percorso all'indietro fino a ^Il'gynoth, Corruption Reborn^.",
    ["Follow the path all the way back to meet the ^Council of Dreams^. Click each of the illusions to start the fight."] = "Segui tutto il percorso all'indietro fino a ^Council of Dreams^. Clicca su ciascuna illusione per iniziare lo scontro.",
    ["Follow the path and kill ^Braekkas^ to open the wall. Continue on to find ^The Primal Council^."] = "Segui il percorso e uccidi ^Braekkas^ per aprire la parete. Continua fino a ^The Primal Council^.",
    ["Follow the path around to ^Hellfire High Council^."] = "Segui il percorso fino a ^Hellfire High Council^.",
    ["Follow the path back out to the main courtyard, and make your way to the ^Captain's Quarters^ entrance on the southwest corner of the map. Inside the ^Captain's Quarters^, take your first right to go up a short stairwell."] = "Segui il percorso fino al cortile principale e dirigiti verso l'ingresso di ^Captain's Quarters^ nell'angolo sud-occidentale della mappa. Dentro ^Captain's Quarters^, prendi la prima a destra e sali la breve tromba delle scale.",
    ["Follow the path down to ^Skolex^. Kill the trash to spawn the boss."] = "Segui il percorso in discesa fino a ^Skolex^. Elimina i nemici per far comparire il boss.",
    ["Follow the path south and continue on to ^The Illidari Council^."] = "Segui il percorso verso sud e continua fino a ^The Illidari Council^.",
    ["Follow the path through ^The Endless Foundry^, killing the trash on the way to ^Lihuvim^."] = "Segui il percorso attraverso ^The Endless Foundry^, eliminando i nemici lungo la strada verso ^Lihuvim^.",
    ["Follow the path through ^The Grand Design^, killing trash on the way to ^Lords of Dread^."] = "Segui il percorso attraverso ^The Grand Design^, eliminando i nemici lungo la strada verso ^Lords of Dread^.",
    ["Follow the path through the next area until you reach ^Teron Gorefiend^."] = "Segui il percorso attraverso l'area successiva finché non raggiungi ^Teron Gorefiend^.",
    ["Follow the path to reach the ^Ascendant Council^."] = "Segui il percorso fino a ^Ascendant Council^.",
    ["Follow the path to the boss area, and clear the trash to spawn ^Volcoross^."] = "Segui il percorso fino all'area del boss ed elimina i nemici per far comparire ^Volcoross^.",
    ["Follow the path to the final map exit labeled ^N'Zoth^. Kill adds on the bridge to spawn a portal at the end."] = "Segui il percorso fino all'ultima uscita della mappa contrassegnata come ^N'Zoth^. Elimina i nemici sul ponte per far comparire un portale alla fine.",
    ["Follow the path to the map exit labeled ^The Hive^."] = "Segui il percorso fino all'uscita della mappa contrassegnata come ^The Hive^.",
    ["Follow the path up and to the left to reach ^Tectus^. Kill the (3) rock golems to spawn the boss."] = "Segui il percorso in salita e a sinistra fino a ^Tectus^. Uccidi i 3 golem di roccia per far comparire il boss.",
    ["Follow the path up the stairs and around to the map exit labeled ^Halls of Opulence^. Jump in the hole at the end of the path."] = "Sali le scale e segui il percorso fino all'uscita della mappa contrassegnata come ^Halls of Opulence^. Salta nella voragine alla fine del percorso.",
    ["Follow the path up to ^Broodkeeper Diurna^."] = "Segui il percorso in salita fino a ^Broodkeeper Diurna^.",
    ["Follow the path. Once you reach the boss room, kill the final trash pack and talk to ^Lorewalker Cho^ to trigger the boss fight with ^Elegon^."] = "Segui il percorso. Una volta nella stanza del boss, elimina l'ultimo gruppo di nemici e parla con ^Lorewalker Cho^ per avviare lo scontro con ^Elegon^.",
    ["Font of Power"] = "Fonte del Potere",
    ["For the knockback, position yourself between the boss and a tornado."] = "Per il respingimento, posizionati tra il boss e un tornado.",
    ["Formation Seed"] = "Seme della Formazione",
    ["Forward then left to Ignis"] = "Avanti, poi a sinistra verso Ignis",
    ["Forward to Imonar"] = "Avanti verso Imonar",
    ["From ^The Primal Convergence^, follow the path to the entrance labeled ^Iceskitter Hollow^."] = "Da ^The Primal Convergence^, segui il percorso fino all'ingresso contrassegnato come ^Iceskitter Hollow^.",
    ["From ^Wellspring Atrium^, take the final remaining exit labeled ^Throne of the Firelord^. Click on the ^Formation Seed^ to construct a bridge to the next area."] = "Da ^Wellspring Atrium^, prendi l'ultima uscita rimasta contrassegnata come ^Throne of the Firelord^. Clicca sul ^Formation Seed^ per costruire un ponte verso l'area successiva.",
    ["From the top of the elevator, proceed ahead up the ramp to find the ^Antoran High Command^."] = "Dalla cima dell'ascensore, sali la rampa per trovare ^Antoran High Command^.",
    ["From the top of the stairs, take your first right. Travel east down the hallway until you reach ^Maiden of Virtue^."] = "Dalla cima delle scale, prendi la prima a destra. Vai a est lungo il corridoio finché non raggiungi ^Maiden of Virtue^.",
    ["Fyrakk additionally drops {item}, an omnitoken that exchanges for any tier slot. Not tracked here."] = "Fyrakk rilascia inoltre {item}, un omnitoken scambiabile con qualsiasi pezzo del completo. Non viene monitorato qui.",
