    ["Wait for Tsulong"] = "Attendi Tsulong",
    ["Walk into (3) Floor Teleporters"] = "Entra nei (3) teletrasporti a pavimento",
    ["Walk into the ^beam of light^ and click the ^Extra Action Button^ to trigger a cutscene. After the cutscene, go up the stairs and jump off the ledge."] = "Entra nel ^beam of light^ e clicca sul ^Extra Action Button^ per avviare un filmato. Dopo il filmato, sali le scale e salta dal bordo.",
    ["Walk over anima orbs to collect them, and bring them to ^Prince Renathal^ to free him."] = "Passa sopra i globi d'Animum per raccoglierli e portali a ^Prince Renathal^ per liberarlo.",
    ["Warden Thul'tok then Portal"] = "Custode Thul’tok, poi portale",
    ["West Exit"] = "Uscita ovest",
    ["West exit"] = "Uscita ovest",
    ["West stairwell"] = "Vano scale ovest",
    ["West then North"] = "A ovest, poi a nord",
    ["West through pipe"] = "Ovest attraverso il tubo",
    ["West to Abyssal Throne"] = "A ovest verso il Trono Abissale",
    ["West to Chimaeron"] = "A ovest verso Chimaeron",
    ["West to Conclave"] = "A ovest verso il Conclave",
